const b = $input.first().json.body ?? $input.first().json;
const courseArr = Array.isArray(b.courses) ? b.courses : (Array.isArray(b.subjects) ? b.subjects : []);
const courses = courseArr.length > 0 ? courseArr.join('、') : '未填';
const studentName = (b.studentName || '').trim() || '未填';
const now = new Date().toLocaleString('zh-TW', { timeZone: 'Asia/Taipei' });

const lineMsg = [
  '【新試聽預約通知】',
  `家長：${b.parentName || '未知'}`,
  `電話：${b.phone || '未填'}`,
  `學生：${studentName}`,
  `年級：${b.grade || '未填'}`,
  `科目：${courses}`,
  `時段：${b.preferredTime || '不限'}`,
  `備注：${(b.note || '').trim() || '無'}`,
  `時間：${now}`
].join('\n');

const emailBody = [
  '【新試聽預約通知】',
  '',
  `家長姓名：${b.parentName || '未知'}`,
  `聯絡電話：${b.phone || '未填'}`,
  `學生姓名：${studentName}`,
  `年級：${b.grade || '未填'}`,
  `有興趣課程：${courses}`,
  `希望時段：${b.preferredTime || '不限'}`,
  `備注：${(b.note || '').trim() || '無'}`,
  '',
  `預約時間：${now}`,
  '',
  '─────────────────────',
  '此信由 Mina n8n 自動發送'
].join('\n');

return [{ json: {
  lineMsg,
  emailBody,
  emailSubject: `【新試聽預約】${b.parentName || '?'} / ${studentName} / ${b.grade || '?'} / ${b.phone || '?'}`
}}];

// 出版社對照（114學年度 旭光）
const publishers = {
  '英文': { '小一':'康軒Wonder World','小二':'康軒Wonder World','小三':'康軒Wonder World',
            '小四':'康軒Wonder World','小五':'何嘉仁Super Fun','小六':'康軒Wonder World' },
  '數學': { '小一':'康軒','小二':'翰林','小三':'康軒','小四':'南一','小五':'康軒','小六':'南一' }
};

const now = new Date();
const nm = (now.getMonth() + 1) % 12;
const ny = now.getMonth() === 11 ? now.getFullYear() + 1 : now.getFullYear();
const sats = [];
const last = new Date(ny, nm + 1, 0);
for (let d = new Date(ny, nm, 1); d <= last; d.setDate(d.getDate() + 1)) {
  if (d.getDay() === 6) sats.push(new Date(d));
}

function schoolWeek(date) {
  const m = date.getMonth() + 1, y = date.getFullYear();
  const syy = m >= 8 ? y : y - 1;
  const upper = new Date(syy, 7, 1);
  const lower = new Date(syy + 1, 1, 1);
  const ms = 7 * 24 * 3600 * 1000;
  if (m >= 2 && m <= 7) return Math.floor((date - lower) / ms) + 19;
  if (m >= 8 || m === 1) return Math.floor((date - upper) / ms) + 1;
  return 0;
}
function acadYear(date) {
  const m = date.getMonth() + 1, y = date.getFullYear();
  return (m >= 8 ? y - 1911 : y - 1912) + '學年度';
}
function sem(date) {
  const m = date.getMonth() + 1;
  return (m >= 8 || m === 1) ? '上學期' : '下學期';
}
function weekOfMonth(date) {
  const y = date.getFullYear(), m = date.getMonth();
  const first = new Date(y, m, 1);
  const offset = (6 - first.getDay() + 7) % 7;
  const firstSat = new Date(y, m, 1 + offset);
  return Math.floor((date - firstSat) / (7 * 24 * 3600 * 1000)) + 1;
}
const grades = ['小一','小二','小三','小四','小五','小六'];
const subjects = ['英文','數學'];
const qTypes = ['標準題型','錯題診斷','觀念拆解'];
const tasks = [];
for (const sat of sats) {
  let wk = schoolWeek(sat) || ((sat.getMonth() + 1 >= 8) ? 1 : 36);
  const publishDate = sat.toISOString().split('T')[0];
  for (const grade of grades) {
    for (const subject of subjects) {
      const publisher = publishers[subject][grade] || '';
      for (const qType of qTypes) {
        tasks.push({ grade, subject, publisher, qType, publishDate,
          semester: sem(sat), acadYear: acadYear(sat), schoolWeek: wk, weekOfMonth: weekOfMonth(sat), count: 1 });
      }
    }
  }
}
return tasks.map(t => ({ json: t }));

let resp, task;
try {
  resp = $input.item.json;
  task = $('建立出題任務清單').item.json;
} catch(e) { return null; }

if (!resp || typeof resp !== 'object' || Array.isArray(resp)) return null;
if (!task || typeof task !== 'object') return null;

const grade = task.grade || '';
const subject = task.subject || '';
const publisher = task.publisher || '';
const semester = task.semester || '';
const acadYear = task.acadYear || '';
const qType = task.qType || '標準題型';
const publishDate = task.publishDate || '';
const schoolWeek = task.schoolWeek || 1;
const wom = task.weekOfMonth || 1;

let raw = '';
try {
  const content = resp.choices[0].message.content;
  raw = (content != null) ? String(content) : '';
} catch(e) { return null; }

raw = raw.replace(/```json/g,'').replace(/```/g,'').trim();

let qs = [];
try {
  const s = raw.indexOf('['), e = raw.lastIndexOf(']');
  if (s !== -1 && e > s) {
    const parsed = JSON.parse(raw.slice(s, e+1));
    if (Array.isArray(parsed)) qs = parsed;
  }
} catch(err) { return null; }

if (qs.length === 0) return null;
const q = qs[0];
if (!q || typeof q !== 'object' || Array.isArray(q)) return null;

const code = subject === '英文' ? 'en' : 'ma';
const gc = {'小一':1,'小二':2,'小三':3,'小四':4,'小五':5,'小六':6}[grade] || 0;
const typeCode = {'標準題型':'標','錯題診斷':'錯','觀念拆解':'觀'}[qType] || '標';
const ym = publishDate.replace(/-/g,'').slice(0,6);
const publishDateISO = publishDate || '';

return {
  json: {
    questionId: code + '-' + gc + '-' + typeCode + '-w' + wom + '-' + ym,
    grade, subject, curriculum: publisher, semester, acadYear, qType,
    chapter:  String(q.chapter  || '').slice(0, 150),
    question: String(q.question || '').slice(0, 150),
    optionA:  String(q.optionA  || '').slice(0, 80), optionB: String(q.optionB || '').slice(0, 80),
    optionC:  String(q.optionC  || '').slice(0, 80), optionD: String(q.optionD || '').slice(0, 80),
    answer:   String(q.answer   || 'A'),
    concept:  String(q.concept  || '').slice(0, 40),
    mistake:  String(q.mistake  || '').slice(0, 40),
    hint:     String(q.hint     || '').slice(0, 40),
    publishDate: publishDateISO
  }
};

const items = $input.all();
const count = items.length;
const now = new Date().toLocaleString('zh-TW', { timeZone: 'Asia/Taipei' });
return [{ json: {
  count,
  lineMsg: '【Mina 自動出題完成】
本月共新增 ' + count + ' 道題目至 Notion 題庫
狀態：待審核
請登入 Notion 審核後勾選「是否發布」
時間：' + now,
  emailSubject: '【Mina 題庫】' + count + ' 道新題目待審核',
  emailBody: 'Mina AI 自動出題完成

共新增：' + count + ' 道題
狀態：待審核

請登入 Notion 題庫 Database，
確認題目無誤後勾選「是否發布」=✓

時間：' + now
}}];

const results = ($input.first().json.results || []);
const today = new Date();
today.setHours(0,0,0,0);

function parseLocal(str) {
  const [y,m,d] = str.split('-').map(Number);
  return new Date(y, m-1, d);
}
function toDateStr(d) {
  return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');
}

const rows = results.map(item => ({
  id: item.id,
  name: (item.properties?.['名稱']?.title?.[0]?.plain_text || '').trim(),
  dateStr: item.properties?.['日期']?.date?.start || '',
})).filter(r => r.name && r.dateStr);

const groups = {};
for (const row of rows) {
  if (!groups[row.name]) groups[row.name] = [];
  groups[row.name].push(row);
}

const qualifying = [];
for (const [name, pages] of Object.entries(groups)) {
  const dates = pages.map(p => parseLocal(p.dateStr)).sort((a,b)=>a-b);
  const daysUntil = Math.round((dates[0] - today) / 86400000);
  if (daysUntil >= 3 && daysUntil <= 21) {
    qualifying.push({
      name,
      pageIds: pages.map(p => p.id),
      examStart: toDateStr(dates[0]),
      examEnd:   toDateStr(dates[dates.length-1]),
      daysUntil,
    });
  }
}

// 無待生題段考 → 停止流程
if (qualifying.length === 0) return [];

// 只處理最近一場（最多 1 場在窗口內）
return [{ json: qualifying[0] }];

const exam     = $('整理考試清單').first().json;
const prevRows = ($input.first().json.results || []);

function parseLocal(str) {
  const [y,m,d] = str.split('-').map(Number);
  return new Date(y, m-1, d);
}
function toDateStr(d) {
  return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');
}

// 學年開始 = 今年/去年 8/1
const today = new Date();
const acadYear = (today.getMonth()+1) >= 8 ? today.getFullYear() : today.getFullYear()-1;
const acadStart = new Date(acadYear, 7, 1);

const examStart = parseLocal(exam.examStart);
const examEnd   = parseLocal(exam.examEnd);

// rangeStart = 上次段考最後日 +1，否則學年8/1
let rangeStartDate;
if (prevRows.length > 0) {
  const lastStr = prevRows[0].properties['日期']?.date?.start;
  rangeStartDate = lastStr ? parseLocal(lastStr) : new Date(acadStart);
  rangeStartDate.setDate(rangeStartDate.getDate() + 1);
} else {
  rangeStartDate = new Date(acadStart);
}
const rangeStart = toDateStr(rangeStartDate);

// rangeEnd = 考試第一天 -1
const reDate = new Date(examStart);
reDate.setDate(reDate.getDate() - 1);
const rangeEnd = toDateStr(reDate);

// openAt = 考前那個週六 03:00 +08:00
function prevSat(d) {
  const t = new Date(d);
  const dow = t.getDay(); // 0=Sun, 6=Sat
  t.setDate(t.getDate() - (dow === 6 ? 7 : dow + 1));
  return t;
}
// closeAt = 考完那個週日 23:59 +08:00
function nextSun(d) {
  const t = new Date(d);
  const dow = t.getDay();
  t.setDate(t.getDate() + (dow === 0 ? 7 : 7 - dow));
  return t;
}

const openAt  = toDateStr(prevSat(examStart)) + 'T03:00:00+08:00';
const closeAt = toDateStr(nextSun(examEnd))   + 'T23:59:00+08:00';

return [{ json: {
  examName:  exam.name,
  pageIds:   exam.pageIds,
  openAt,
  closeAt,
  rangeStart,
  rangeEnd,
} }];

const params = $('計算考試參數').first().json;
const res    = $input.first().json;
const ok     = res.ok !== false && !res.error;
const openD  = params.openAt.slice(0,10).replace(/-/g,'/');
const closeD = params.closeAt.slice(0,10).replace(/-/g,'/');
const msg = ok
  ? '📋 ' + params.examName + ' 考前複習卷已生成\n\n'
  + '請至 Notion 審核（英數各年級共12份）\n'
  + '📅 開放：' + openD + ' ～ ' + closeD
  : '⚠️ B1 生題失敗\n考試：' + params.examName + '\n錯誤：' + (res.error?.message || JSON.stringify(res).slice(0,100));
return [{ json: { msg } }];

const s = $('讀取出題DB設定').first().json;
const dbId = s.data?.notionPracticeDbId || '';
const now = new Date();
const today = now.toISOString().split('T')[0];
const archiveCutoff = new Date(now - 180 * 24 * 3600 * 1000).toISOString().split('T')[0];
return [{ json: { dbId, today, archiveCutoff } }];

const res = $input.first().json;
const pages = res.results || [];
if (pages.length === 0) return [{ json: { pageId: '__NONE__' } }];
return pages.map(p => ({ json: { pageId: p.id } }));

const items = $input.all();
const count = items.filter(i => i.json.object === 'page').length;
return [{ json: { publishedCount: count } }];

const res = $input.first().json;
const pages = res.results || [];
if (pages.length === 0) return [{ json: { pageId: '__NONE__' } }];
return pages.map(p => ({ json: { pageId: p.id } }));

const items = $input.all();
const count = items.filter(i => i.json.object === 'page').length;
return [{ json: { archivedCount: count } }];

const pub = $('計數已發布').first().json.publishedCount || 0;
const arc = $('計數已封存').first().json.archivedCount || 0;
const today = $('計算目標日期').first().json.today;
const msg = `✅ 週六自動作業完成（${today}）\n\n📢 今日發布：${pub} 題\n🗄️ 封存舊題：${arc} 題`;
return [{ json: { msg, pub, arc } }];

const now = new Date();
const roc = now.getFullYear() - 1911;
const dbName = roc + '學年度題庫';
const parentPageId = '374b8ee1-06b4-80ea-a0f9-dccaae830e8a';
return [{ json: { roc, dbName, parentPageId } }];

const newDbId = $('建立新學年度DB').first().json.id || '';
const dbName  = $('計算新學年度').first().json.dbName;
const ok = !!newDbId;
const msg = ok
  ? '✅ A3 完成！\n\n📚 新題庫：' + dbName + '\n🆔 ID：' + newDbId + '\n\nA1 出題從今日起寫入新題庫，8/1 網站將正式切換。'
  : '⚠️ A3 建立新題庫 DB 失敗，請手動確認！';
return [{ json: { msg, ok, newDbId, dbName } }];

const s = $input.first().json;
const genDbId = (s.data && s.data.notionPracticeGenDbId) || '';
const curDbId = (s.data && s.data.notionPracticeDbId)    || '';
const needsSwitch = !!(genDbId && genDbId !== curDbId);
return [{ json: { genDbId, curDbId, needsSwitch } }];

const st = $('檢查DB狀態').first().json;
const genDbId = st.genDbId;
const curDbId = st.curDbId;
const switched = st.needsSwitch;
const deleted = ($('清除KV快取').first().json.data || {}).deleted || 0;
const msg = switched
  ? '✅ A4 DB 切換完成！\n\n🔄 舊DB：' + curDbId.slice(0,8) + '…\n✨ 新DB：' + genDbId.slice(0,8) + '…\n🗑️ 清除快取：' + deleted + ' 筆\n\n網站現在已讀取新學年度題庫。'
  : '⚠️ A4 執行：兩個 DB ID 相同（A3 尚未執行？），無需切換。';
return [{ json: { msg, switched } }];

const now = new Date().toISOString();
const posts = $input.first().json.posts || [];
const due = posts.filter(p => p.scheduled_time && p.scheduled_time <= now && !p.is_publishing);
return due.map(p => ({ json: p }));

const result = $input.first().json;
if (!result.ok) throw new Error('n8n backup failed: ' + JSON.stringify(result));
console.log('n8n backup OK:', result.path, '(' + result.workflow_count + ' workflows)');
return [{ json: result }];

const files = $input.first().json;
if (!Array.isArray(files)) return [];
const cutoff = new Date();
cutoff.setDate(cutoff.getDate() - 90);
const old = files.filter(f => {
  const match = f.name.match(/^(\d{4}-\d{2}-\d{2})\.json$/);
  if (!match) return false;
  return new Date(match[1]) < cutoff;
});
console.log('Old backups to delete:', old.map(f => f.name));
return old.map(f => ({ json: { name: f.name, sha: f.sha, path: f.path } }));
